#!/usr/bin/env python3
"""Generate the VS Code agent, Claude subagent, and Gemini skill from src/ian.md."""

import argparse
import difflib
import re
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SOURCE = ROOT / "src" / "ian.md"
NOTICE = (
    "<!-- GENERATED from src/ian.md. Do not edit this file; "
    "edit the source and run `docker compose run --rm sync`. -->"
)

TARGETS = {
    "vscode": {
        "path": ROOT / ".github" / "agents" / "ian.agent.md",
        "vars": {"kind": "agent", "workspace": "workspace", "where": "here or in the workspace"},
        "frontmatter": """\
---
name: "Ian"
description: "Use when you want to know how Ian works, thinks, or likes things formatted: ask about his preferences for commits, PRs, docs, specs, naming, code, and architecture, or get your work reviewed against them. Platform engineering, Google Cloud, Azure, C#, Angular, Go."
argument-hint: "Ask how Ian would approach something, what format he expects, or paste work for review"
tools: [read, search, edit, web, execute]
model: "Claude Sonnet 5.5 (copilot)"
reasoning-effort: high
---
""",
    },
    "claude": {
        "path": ROOT / ".claude" / "agents" / "ian.md",
        "vars": {"kind": "agent", "workspace": "project", "where": "here or in the project"},
        # Description is quoted because it contains ": ", which breaks a plain YAML scalar.
        "frontmatter": """\
---
name: ian
description: "Use when asked how Ian works, thinks, or likes things formatted: his preferences for commits, PRs, docs, specs, naming, code, and architecture, or to review work against them. Platform engineering, Google Cloud, Azure, C#, Angular, Go."
tools: Read, Grep, Glob, Edit, Write, WebFetch, WebSearch
model: sonnet
effort: high
---
""",
    },
    "gemini": {
        "path": ROOT / "skills" / "ian" / "SKILL.md",
        "vars": {"kind": "skill", "workspace": "workspace", "where": "here"},
        "frontmatter": """\
---
name: ian
description: "Use when asked how Ian works, what he prefers, or when work should be reviewed against his standards: commit messages, pull requests, documents, naming and casing, diagrams, CLI tool language choice, and local build/run/test setup. Applies to platform engineering, Google Cloud, Azure, C#, Angular, and Go."
---
""",
    },
}

ONLY_OPEN = re.compile(r"^<!-- only: (.+?) -->$")
ONLY_CLOSE = "<!-- /only -->"
PLACEHOLDER = re.compile(r"\{\{(\w+)\}\}")


def render(name: str, source: str) -> str:
    target = TARGETS[name]
    body = re.sub(r"\A<!--.*?-->\s*", "", source, count=1, flags=re.S)

    kept, active = [], None
    for line in body.splitlines():
        opened = ONLY_OPEN.match(line.strip())
        if opened:
            if active is not None:
                sys.exit("src/ian.md: nested 'only' blocks are not supported")
            active = {t.strip() for t in opened.group(1).split(",")}
            unknown = active - TARGETS.keys()
            if unknown:
                sys.exit(f"src/ian.md: unknown target(s) in 'only': {', '.join(sorted(unknown))}")
        elif line.strip() == ONLY_CLOSE:
            if active is None:
                sys.exit("src/ian.md: '/only' without matching 'only'")
            active = None
        elif active is None or name in active:
            kept.append(line)
    if active is not None:
        sys.exit("src/ian.md: 'only' block is never closed")

    def substitute(match: re.Match) -> str:
        key = match.group(1)
        if key not in target["vars"]:
            sys.exit(f"src/ian.md: unknown placeholder {{{{{key}}}}}")
        return target["vars"][key]

    text = PLACEHOLDER.sub(substitute, "\n".join(kept))
    return f"{target['frontmatter']}\n{NOTICE}\n\n{text.strip()}\n"


def package(destination: Path) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    paths = sorted(t["path"] for t in TARGETS.values())
    with zipfile.ZipFile(destination, "w", zipfile.ZIP_DEFLATED) as archive:
        for path in paths:
            # Fixed timestamp and mode keep the archive reproducible.
            # Each agent gets its own folder so several agents never collide on names like SKILL.md.
            info = zipfile.ZipInfo(f"{SOURCE.stem}/{path.name}", date_time=(1980, 1, 1, 0, 0, 0))
            info.external_attr = 0o644 << 16
            info.compress_type = zipfile.ZIP_DEFLATED
            archive.writestr(info, path.read_bytes())
    print(f"packaged {len(paths)} files into {destination}")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if generated files are out of date")
    parser.add_argument(
        "--package",
        type=Path,
        metavar="ZIP",
        help="check the generated files, then write only those files to a zip",
    )
    args = parser.parse_args()
    check = args.check or args.package is not None

    source = SOURCE.read_text(encoding="utf-8")
    drifted = []
    for name, target in TARGETS.items():
        path = target["path"]
        expected = render(name, source)
        current = path.read_text(encoding="utf-8") if path.exists() else ""
        if current == expected:
            continue
        rel = path.relative_to(ROOT)
        if check:
            drifted.append(rel)
            sys.stdout.writelines(
                difflib.unified_diff(
                    current.splitlines(keepends=True),
                    expected.splitlines(keepends=True),
                    fromfile=f"{rel} (committed)",
                    tofile=f"{rel} (expected)",
                    n=1,
                )
            )
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(expected, encoding="utf-8")
            print(f"updated {rel}")

    if drifted:
        print(
            "\nGenerated files are out of date: "
            + ", ".join(str(p) for p in drifted)
            + "\nMove any edits into src/ian.md, then run: docker compose run --rm sync",
            file=sys.stderr,
        )
        return 1
    if args.package is not None:
        package(args.package)
    elif args.check:
        print("all generated files are up to date")
    return 0


if __name__ == "__main__":
    sys.exit(main())
